pub const WASMOS_ERR_ENV_TABLE_FULL: i32 = -0x00160003; // no free entry remains
pub const WASMOS_ERR_FRAMEBUFFER_NOT_PRESENT: i32 = -0x00170001; // no framebuffer is available on this system
pub const WASMOS_ERR_FRAMEBUFFER_TOO_SMALL: i32 = -0x00170002; // the caller's requested mapping is smaller than the framebuffer
pub const WASMOS_ERR_DEVMGR_NO_MOUNT_RULE: i32 = -0x000A0001; // no block/filesystem mount rule matches the requested unit
pub const WASMOS_ERR_DEVMGR_UNSUPPORTED_QUERY: i32 = -0x000A0002; // unknown or unsupported device-manager query type

pub fn errMake(dom: u16, code: u16) i32 {
    return -@as(i32, @intCast((@as(u32, dom) << 16) | @as(u32, code)));
}
pub fn errDomainOf(x: i32) u16 {
    return @intCast(@as(u32, @intCast(-x)) >> 16);
}
pub fn errCodeOf(x: i32) u16 {
    return @intCast(@as(u32, @intCast(-x)) & 0xffff);
}

pub fn statusStr(s: i32) []const u8 {
    return switch (s) {
        WASMOS_OK => "OK",
        WASMOS_INVAL => "INVAL",
        WASMOS_DENIED => "DENIED",
        WASMOS_FULL => "FULL",
        WASMOS_NOENT => "NOENT",
        WASMOS_TIMEOUT => "TIMEOUT",
        WASMOS_NOMEM => "NOMEM",
        WASMOS_UNSUPPORTED => "UNSUPPORTED",
        WASMOS_PEER_GONE => "PEER_GONE",
        WASMOS_AGAIN => "AGAIN",
        else => "UNKNOWN_STATUS",
    };
}

pub fn errorDomainName(d: u16) []const u8 {
    return switch (d) {
        WASMOS_ERR_DOMAIN_NONE => "none",
        WASMOS_ERR_DOMAIN_PROC_SPAWN => "proc_spawn",
        WASMOS_ERR_DOMAIN_PROC_PM => "proc_pm",
        WASMOS_ERR_DOMAIN_SHMEM => "shmem",
        WASMOS_ERR_DOMAIN_FS => "fs",
        WASMOS_ERR_DOMAIN_NET => "net",
        WASMOS_ERR_DOMAIN_GFX => "gfx",
        WASMOS_ERR_DOMAIN_DRIVER => "driver",
        WASMOS_ERR_DOMAIN_VT => "vt",
        WASMOS_ERR_DOMAIN_CHARDEV => "chardev",
        WASMOS_ERR_DOMAIN_HRNG => "hrng",
        WASMOS_ERR_DOMAIN_DMA => "dma",
        WASMOS_ERR_DOMAIN_IRQ => "irq",
        WASMOS_ERR_DOMAIN_MSI => "msi",
        WASMOS_ERR_DOMAIN_IO => "io",
        WASMOS_ERR_DOMAIN_FONT => "font",
        WASMOS_ERR_DOMAIN_RTC => "rtc",
        WASMOS_ERR_DOMAIN_XFER_BUFFER => "xfer_buffer",
        WASMOS_ERR_DOMAIN_KERNEL => "kernel",
        WASMOS_ERR_DOMAIN_BLOCK => "block",
        WASMOS_ERR_DOMAIN_THREAD => "thread",
        WASMOS_ERR_DOMAIN_ENV => "env",
        WASMOS_ERR_DOMAIN_FRAMEBUFFER => "framebuffer",
        WASMOS_ERR_DOMAIN_DEVMGR => "devmgr",
        else => "unknown",
    };
}

